class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        """
        方法一：排序比較
        時間複雜度: O(n log n)
        空間複雜度: O(n)
        """
        return sorted(s) == sorted(t)

    def isAnagram_hashmap(self, s: str, t: str) -> bool:
        """
        方法二：哈希表計數（推薦）
        時間複雜度: O(n)
        空間複雜度: O(1) - 最多 26 個小寫字母
        """
        # 長度不同直接返回 false
        if len(s) != len(t):
            return False

        # 統計字符頻率
        count = {}

        # 計算 s 中每個字符的出現次數
        for char in s:
            count[char] = count.get(char, 0) + 1

        # 減少 t 中對應字符的計數
        for char in t:
            if char not in count:
                return False
            count[char] -= 1
            if count[char] < 0:
                return False

        # 檢查所有計數是否都為 0
        return all(c == 0 for c in count.values())

    def isAnagram_counter(self, s: str, t: str) -> bool:
        """
        方法二：使用 Counter（Python 專用）
        時間複雜度: O(n)
        空間複雜度: O(1)
        """
        from collections import Counter
        return Counter(s) == Counter(t)

    def isAnagram_array(self, s: str, t: str) -> bool:
        """
        方法三：陣列計數（最優）
        時間複雜度: O(n)
        空間複雜度: O(1)
        """
        if len(s) != len(t):
            return False

        # 長度 26 的陣列，對應 a-z
        count = [0] * 26

        # 統計字符差異
        for i in range(len(s)):
            count[ord(s[i]) - ord('a')] += 1
            count[ord(t[i]) - ord('a')] -= 1

        # 檢查是否所有計數都為 0
        return all(c == 0 for c in count)

