#include <string>
#include <algorithm>
#include <unordered_map>
#include <vector>

class Solution {
public:
    /**
     * 方法一：排序比較
     * 時間複雜度: O(n log n)
     * 空間複雜度: O(n)
     */
    bool isAnagram(std::string s, std::string t) {
        std::sort(s.begin(), s.end());
        std::sort(t.begin(), t.end());
        return s == t;
    }

    /**
     * 方法二：哈希表計數
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    bool isAnagram_hashmap(std::string s, std::string t) {
        if (s.length() != t.length()) {
            return false;
        }

        std::unordered_map<char, int> count;

        // 統計 s 中字符頻率
        for (char c : s) {
            count[c]++;
        }

        // 減少 t 中對應字符的計數
        for (char c : t) {
            if (count.find(c) == count.end() || count[c] == 0) {
                return false;
            }
            count[c]--;
        }

        return true;
    }

    /**
     * 方法三：陣列計數（最優）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    bool isAnagram_array(std::string s, std::string t) {
        if (s.length() != t.length()) {
            return false;
        }

        std::vector<int> count(26, 0);

        for (int i = 0; i < s.length(); i++) {
            count[s[i] - 'a']++;
            count[t[i] - 'a']--;
        }

        for (int c : count) {
            if (c != 0) return false;
        }

        return true;
    }
};

