// 計數陣列：s 的字元 +1、t 的字元 -1，最後全部要是 0
// 時間複雜度: O(n)，空間複雜度: O(1)（固定 26 格）
bool isAnagram(char* s, char* t) {
    if (strlen(s) != strlen(t)) return false;
    int count[26] = {0};
    for (int i = 0; s[i]; i++) {
        count[s[i] - 'a']++;
        count[t[i] - 'a']--;
    }
    for (int i = 0; i < 26; i++) {
        if (count[i] != 0) return false;
    }
    return true;
}

